// Lookup: client_id → webhooks Discord do cliente + role on-call
// TODO: substituir por n8n Data Table quando criar a tabela dryos_clients
const CLIENTS = {
  // Exemplo — copie esse bloco pra cada cliente real
  "f1234567-89ab-cdef-0123-456789abcdef": {
    name: "Altis Lisboa",
    webhook_frentes:   "https://discord.com/api/webhooks/REPLACE/ME",
    webhook_sla:       "https://discord.com/api/webhooks/REPLACE/ME",
    webhook_sla_high:  "https://discord.com/api/webhooks/REPLACE/ME",
    role_oncall_id:    "REPLACE_ROLE_ID"
  }
};

const item = $input.first().json;
const clientId = item.operation && item.operation.client && item.operation.client.id;

if (!clientId) {
  throw new Error("Payload sem operation.client.id — checar contrato");
}

const config = CLIENTS[clientId];
if (!config) {
  // Cliente desconhecido: não bloqueia o fluxo, só sinaliza.
  // Considere adicionar branch de fallback pra canal de erros.
  throw new Error(`Cliente sem config no lookup: ${clientId}`);
}

return [{ json: { ...item, _config: config } }];

// Build embed Discord — frente_stale
const it = $input.first().json;

const staleDays = it.context.stale_days;
const color = staleDays >= 14 ? 11680328 : 13211454; // critical vs oak
const emoji  = staleDays >= 14 ? "🔴" : "🟡";

const body = {
  embeds: [{
    title: `${emoji} Frente parada há ${staleDays}d`,
    description: `**${it.subject.name}**\n${it.context.actionable_status}`,
    url: it.url,
    color: color,
    fields: [
      { name: "Operação", value: `${it.operation.client.name} · ${it.operation.name}`, inline: false }
    ],
    footer: { text: `DRYOS Studio · ${it.operation.client.name}` },
    timestamp: it.ts
  }]
};

return [{ json: { _webhook_url: it._config.webhook_frentes, _body: body } }];

// Build embed Discord — sla_breach severity HIGH (com role ping)
const it = $input.first().json;

const kindLabel = it.context.breach_kind === "response" ? "sem resposta" : "não resolvido";

const body = {
  content: `<@&${it._config.role_oncall_id}> SLA crítico`,
  embeds: [{
    title: `🚨 SLA ${kindLabel} · ${it.context.hours_elapsed}h / ${it.context.hours_limit}h`,
    description: `**${it.subject.name}**`,
    url: it.url,
    color: 11680328,
    fields: [
      { name: "Operação", value: `${it.operation.client.name} · ${it.operation.name}`, inline: true },
      { name: "Severidade", value: it.context.severity, inline: true }
    ],
    footer: { text: `DRYOS Studio · ${it.operation.client.name}` },
    timestamp: it.ts
  }]
};

return [{ json: { _webhook_url: it._config.webhook_sla_high, _body: body } }];

// Build embed Discord — sla_breach severity low/medium (sem ping)
const it = $input.first().json;

const kindLabel = it.context.breach_kind === "response" ? "sem resposta" : "não resolvido";

const body = {
  embeds: [{
    title: `⚠️ SLA ${kindLabel} · ${it.context.hours_elapsed}h / ${it.context.hours_limit}h`,
    description: `**${it.subject.name}**`,
    url: it.url,
    color: 13211454,
    fields: [
      { name: "Operação", value: `${it.operation.client.name} · ${it.operation.name}`, inline: true },
      { name: "Severidade", value: it.context.severity, inline: true }
    ],
    footer: { text: `DRYOS Studio · ${it.operation.client.name}` },
    timestamp: it.ts
  }]
};

return [{ json: { _webhook_url: it._config.webhook_sla, _body: body } }];
